//! Independent references near -1/e, generated by scripts/generate_branch_point_answers.py.

use lambert_w::{
    lambert_w0, lambert_w0f, lambert_wm1, lambert_wm1f, sp_lambert_w0, sp_lambert_wm1, NEG_INV_E,
};

#[test]
fn real_branches_match_high_precision_near_branch_point() {
    for line in include_str!("branch_point.csv").lines().skip(1) {
        let fields: Vec<_> = line.split(',').collect();
        let z: f64 = fields[1].parse().unwrap();
        for (branch, expected) in fields[2..].iter().enumerate() {
            let expected: f64 = expected.parse().unwrap();
            if fields[0] == "f64" {
                // Four epsilons allow the advertised 50-bit approximation error.
                // The reduced-precision functions target 24 bits; f32 arithmetic
                // needs a further rounding allowance in the rational evaluation.
                let accurate = [lambert_w0, lambert_wm1][branch](z);
                let fast = [sp_lambert_w0, sp_lambert_wm1][branch](z);
                assert!(
                    (accurate - expected).abs() <= 4.0 * f64::EPSILON * expected.abs(),
                    "branch {branch}, z={z:?}: {accurate:?} != {expected:?}"
                );
                assert!(
                    (fast - expected).abs() <= f64::from(f32::EPSILON) * expected.abs(),
                    "fast branch {branch}, z={z:?}: {fast:?} != {expected:?}"
                );
            } else {
                let actual = [lambert_w0f, lambert_wm1f][branch](z as f32);
                assert!(
                    (f64::from(actual) - expected).abs()
                        <= 4.0 * f64::from(f32::EPSILON) * expected.abs(),
                    "f32 branch {branch}, z={z:?}: {actual:?} != {expected:?}"
                );
            }
        }
    }
}

#[test]
fn real_branches_separate_monotonically_from_endpoint() {
    for branch in [lambert_w0, sp_lambert_w0, lambert_wm1, sp_lambert_wm1] {
        let mut previous: f64 = -1.0;
        for i in 1..=128 {
            let z = f64::from_bits(NEG_INV_E.to_bits() - i);
            let value = branch(z);
            assert!((value + 1.0).abs() > (previous + 1.0).abs());
            previous = value;
        }
    }
    for branch in [lambert_w0f, lambert_wm1f] {
        let mut previous: f32 = -1.0;
        for i in 1..=128 {
            let z = f32::from_bits((NEG_INV_E as f32).to_bits() - i);
            let value = branch(z);
            assert!((value + 1.0).abs() > (previous + 1.0).abs());
            previous = value;
        }
    }
}

#[test]
fn real_branches_preserve_endpoint_and_domain() {
    for branch in [lambert_w0, lambert_wm1, sp_lambert_w0, sp_lambert_wm1] {
        assert_eq!(branch(NEG_INV_E), -1.0);
        assert!(branch(f64::from_bits(NEG_INV_E.to_bits() + 1)).is_nan());
        assert!(branch(f64::NAN).is_nan());
    }
    let endpoint = NEG_INV_E as f32;
    for branch in [lambert_w0f, lambert_wm1f] {
        assert_eq!(branch(endpoint), -1.0);
        assert!(branch(f32::from_bits(endpoint.to_bits() + 1)).is_nan());
        assert!(branch(f32::NAN).is_nan());
    }
}
